      // 处理公交信息
      if (this.currentTrafficType === 'bus' && trafficTypeData.description) {
        // 从描述中提取公交信息，例如："268路（乘坐6站） 步行300米"
        data.busInfo = this.parseBusInfo(trafficTypeData.description);
      }
