      request({
        url: config.backHost + "/attractionComment/getByAttractionId/" + this.$route.query.id
      }).then(res => {
        if (res.code === 200) {
          this.comments = res.data;
        }
      });
    },
    submitComment() {
      if (!this.commentForm.commentDetail) return this.$message.warning("请输入评价内容");
      this.submitting = true;
      request({
        url: config.backHost + "/attractionComment/addComment",
        data: this.commentForm
      }).then(res => {
        if (res.code === 200) {
          this.$message.success("发布成功");
          this.commentForm.commentDetail = "";
          this.commentForm.pictureUrl = "[]";
          location.reload();
        }
      }).finally(() => this.submitting = false);
    },
    handleDelete(id) {
      this.$confirm('确认删除？删除后不可回退', '温馨提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        request({
          url: config.backHost + `/attractionComment/delById/${id}`
        }).then(res => {
          if (res.code === 200) this.getComment();
        });
      });
    },
    selTicket(ticket) {
      this.selectedTicketId = ticket.id;
      this.currentPrice = ticket.ticketPrice;
    },
    async getDetail() {
      const id = this.$route.query.id;
      const res = await request({
        url: config.backHost + `/attractionInfo/getById/${id}`
      });
      if (res.code === 200) {
        this.detail = res.data;
        this.parsePics();
        this.getClassify();
        this.getTickets(id);
      }
    },
    getClassify() {
      request({
        url: config.backHost + "/attractionType/list"
      }).then(res => {
        if (res.code === 200) {
          this.classify = res.data;
        }
      });
    },
    async getTickets(id) {
      const res = await request({
        url: config.backHost + "/ticketInfo/listPage",
        method: "POST",
        data: {
          params: {
            attractionId: id
          },
          pageBean: {
            page: 1,
            pageSize: -1
          }
        }
      });
      if (res.code === 200) {
        this.ticketList = res.data;
        if (this.ticketList.length > 0) {
          this.selTicket(this.ticketList[0]);
        }
      }
    },
    parsePics() {
      if (this.detail.attractionPic) {
        try {
          const list = JSON.parse(this.detail.attractionPic);
          this.picList = list.map(item => config.backHost + '/file/download/' + item.id);
        } catch (e) {
          this.picList = [this.getPicUrlByJson(this.detail.attractionPic, 0)];
        }
      }
    },
    handleCollect() {
      this.setCollect();
    },
    setCollect() {
      let url = '';
      if (this.detail.isCollect == 1) {
        url = '/attractionCollection/noCollect/' + this.detail.id;
      } else {
        url = '/attractionCollection/collect/' + this.detail.id;
      }
      request({
        url: config.backHost + url
      }).then(res => {
        if (res.code === 200) {
          this.$message.success(res.msg);
          this.getDetail();
        }
      });
    },
    handleOrder() {
      this.$confirm('是否确认预订?', '提示', {
        confirmButtonText: '确认',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        request({
          url: config.backHost + '/attractionOrder/submit',
          data: {
            "attractionId": this.$route.query.id,
            "ticketId": this.selectedTicketId,
            "buyCount": this.visitorTypes[0].count,
            "totalPrice": this.currentPrice * this.visitorTypes[0].count
          }
        }).then(res => {
          document.querySelector("body").innerHTML = res.data;
          document.forms[0].submit();
        });
      });
    },
    // 加载路线推荐
    async loadRouteRecommend() {
      const attractionId = this.$route.query.id;
      if (!attractionId) return;
      this.routeLoading = true;
      try {
        const res = await getNextAttraction(attractionId);
        if (res.code === 200) {
          this.nextAttractions = res.data || [];
        }
      } catch (error) {
        console.error('加载路线推荐失败:', error);
        this.$message.error('加载路线推荐失败');
      } finally {
        this.routeLoading = false;
      }
    },
    // 选择景点
    async selectAttraction(item) {
      this.selectedAttractionId = item.id;

      // 加载交通信息和小吃信息
      await Promise.all([this.loadTrafficInfo(item), this.loadFoodShops(item)]);
    },
    // 加载交通信息
    async loadTrafficInfo(item) {
      this.trafficLoading = true;
      try {
        const params = {
          fromAttractionId: this.$route.query.id,
          toAttractionId: item.id
        };
        const res = await getTrafficInfo(params);
        if (res.code === 200 && res.data && Object.keys(res.data).length > 0) {
          const data = res.data;
          this.trafficInfo = {
            distance: data.distance || 0,
            drive: data.drive || null,
            bus: data.bus || null,
            taxi: data.taxi || null
          };

          // 加载完成后，如果有polyline数据，自动绘制地图
          this.$nextTick(() => {
            if (this.currentTrafficData && this.currentTrafficData.polyline) {
              this.drawRouteOnMap(this.currentTrafficData.polyline);
            }
            // 生成导航二维码
            this.generateNavQRCode();
          });
        } else {
          this.trafficInfo = null;
          this.$message.warning('该路线暂无交通信息');
        }
      } catch (error) {
        console.error('加载交通信息失败:', error);
        this.$message.error('加载交通信息失败');
        this.trafficInfo = null;
      } finally {
        this.trafficLoading = false;
      }
    },
    // 加载沿途小吃
    async loadFoodShops(item) {
      this.foodLoading = true;
      try {
        const params = {
          fromAttractionId: this.$route.query.id,
          toAttractionId: item.id
        };
        const res = await getNearFoodShop(params);
        if (res.code === 200) {
          this.foodShops = res.data || [];
        }
      } catch (error) {
        console.error('加载小吃信息失败:', error);
        this.foodShops = [];
      } finally {
        this.foodLoading = false;
      }
    },
    // 切换交通方式
    switchTrafficType(type) {
      this.currentTrafficType = type;
      // 清除旧的小吃店标记
      if (this.mapInstance && this.foodMarkers.length > 0) {
        this.foodMarkers.forEach(marker => {
          this.mapInstance.remove(marker);
        });
        this.foodMarkers = [];
      }
      // 切换后重新绘制地图路线
      this.$nextTick(() => {
        if (this.currentTrafficData && this.currentTrafficData.polyline) {
          this.drawRouteOnMap(this.currentTrafficData.polyline);
        }
      });
    },
    // 格式化游玩时间（分钟转小时）
    formatPlayTime(minutes) {
      if (!minutes) return '';
      if (minutes < 60) {
        return `${minutes}分钟`;
      }
      const hours = Math.floor(minutes / 60);
      const mins = minutes % 60;
      if (mins === 0) {
        return `${hours}小时`;
      }
      return `${hours}小时${mins}分钟`;
    },
    // 跳转到小吃详情页
    goToFoodDetail(foodId) {
      this.$router.push({
        name: 'foodDetail',
        query: {
          id: foodId
        }
      });
    },
    // 打开高德地图导航（电脑版）
    openPCNavigation() {
      if (!this.trafficInfo || !this.selectedAttractionId) {
        this.$message.warning('请先选择景点');
        return;
      }

      // 获取起点和终点信息
      const fromAttraction = this.detail; // 当前景点（起点）
      const toAttraction = this.nextAttractions.find(a => a.id === this.selectedAttractionId); // 目标景点（终点）

      if (!fromAttraction || !toAttraction) {
        this.$message.error('景点信息不完整');
        return;
      }

      // 检查坐标是否存在
      if (!fromAttraction.longitude || !fromAttraction.latitude || !toAttraction.longitude || !toAttraction.latitude) {
        this.$message.error('景点坐标信息缺失');
        return;
      }

      // 确定导航类型
      let type = 'drive'; // 默认驾车
      if (this.currentTrafficType === 'bus') {
        type = 'bus'; // 公交
      } else if (this.currentTrafficType === 'taxi') {
        type = 'drive'; // 打车也用驾车模式
      }

      // 电脑端网页版链接（无途经点）
      const fromCoord = `${fromAttraction.longitude},${fromAttraction.latitude}`;
      const toCoord = `${toAttraction.longitude},${toAttraction.latitude}`;
      const url = `https://ditu.amap.com/navi?from=${fromCoord}&to=${toCoord}&type=${type}`;
      window.open(url, '_blank');
    },
    // 生成导航二维码
    async generateNavQRCode() {
      if (!this.trafficInfo || !this.selectedAttractionId) {
        return;
      }

      // 获取起点和终点信息
      const fromAttraction = this.detail;
      const toAttraction = this.nextAttractions.find(a => a.id === this.selectedAttractionId);
      if (!fromAttraction || !toAttraction) {
        return;
      }

      // 检查坐标
      if (!fromAttraction.longitude || !fromAttraction.latitude || !toAttraction.longitude || !toAttraction.latitude) {
        return;
      }

      // 确定导航类型
      let t = 'car'; // 默认驾车
      if (this.currentTrafficType === 'bus') {
        t = 'bus'; // 公交
      } else if (this.currentTrafficType === 'taxi') {
        t = 'car'; // 打车也用驾车模式
      }

      // 拼接途经点字符串，格式：lng1,lat1|lng2,lat2，最多16个
      const waypoints = this.foodShops.slice(0, 16) // 高德最多支持16个途经点
      .map(shop => {
        const lng = shop.longitude || shop.lng || shop.shopLongitude || shop.shopLng;
        const lat = shop.latitude || shop.lat || shop.shopLatitude || shop.shopLat;
        return lng && lat ? `${lng},${lat}` : null;
      }).filter(Boolean).join('|');

      // 高德APP跳转链接（带途经点）
      this.navSchemeUrl = `amapuri://route/plan/?sourceApplication=贵阳旅游攻略系统&sname=${fromAttraction.attractionName || '起点'}&slon=${fromAttraction.longitude}&slat=${fromAttraction.latitude}&dname=${toAttraction.attractionName || '终点'}&dlon=${toAttraction.longitude}&dlat=${toAttraction.latitude}&waypoints=${waypoints}&t=${t}&dev=0`;
      try {
        // 生成Base64格式的二维码图片
        this.navQRCodeUrl = await QRCode.toDataURL(this.navSchemeUrl, {
          width: 128,
          margin: 2,
          color: {
            dark: '#0091ff',
            light: '#ffffff'
          }
        });
      } catch (error) {
        console.error('生成二维码失败:', error);
      }
    },
    // 初始化高德地图
    initAMap() {
      return new Promise((resolve, reject) => {
        // 如果已经加载过，直接返回
        if (window.AMap) {
          resolve(window.AMap);
          return;
        }

        // 注意：这里需要替换为你自己的 Web JS API Key
        // 当前使用的 Key 是后端 Web 服务 API 的 Key，不适用于前端
        // 请前往高德开放平台申请 Web JS API 类型的 Key
        const amapKey = '3daadfdc3572b07db886a75a73bb0087'; // Web JS API Key

        // 创建script标签加载高德地图API
        const script = document.createElement('script');
        script.type = 'text/javascript';
        script.src = `https://webapi.amap.com/maps?v=2.0&key=${amapKey}`;
        script.onload = () => {
          resolve(window.AMap);
        };
        script.onerror = () => {
          reject(new Error('高德地图API加载失败，请检查Key是否正确'));
        };
        document.head.appendChild(script);
      });
    },
    // 在地图上绘制路线
    async drawRouteOnMap(polyline) {
      this.mapLoading = true; // 显示 loading

      try {
        // 初始化高德地图
        const AMap = await this.initAMap();

        // 如果地图实例不存在，创建新地图
        if (!this.mapInstance) {
          this.mapInstance = new AMap.Map('amap-container', {
            zoom: 12,
            center: [106.7134, 26.5783],
            // 贵阳市中心坐标作为默认中心点
            viewMode: '2D'
          });
        }

        // 清除之前的路线和标记
        if (this.polylineInstance) {
          this.mapInstance.remove(this.polylineInstance);
        }
        if (this.startMarker) {
          this.mapInstance.remove(this.startMarker);
        }
        if (this.endMarker) {
          this.mapInstance.remove(this.endMarker);
        }

        // 如果有 polyline 数据，绘制路线
        let path = [];
        if (polyline) {
          path = this.parsePolyline(polyline);
        }

        // 添加起点和终点标记（无论有没有路线都显示）
        if (path.length > 0) {
          // 起点标记（绿色）
          this.startMarker = new AMap.Marker({
            position: path[0],
            icon: new AMap.Icon({
              size: new AMap.Size(25, 34),
              image: 'https://a.amap.com/jsapi_demos/static/demo-center/icons/poi-marker-default.png',
              imageSize: new AMap.Size(25, 34)
            }),
            offset: new AMap.Pixel(-13, -30),
            title: '起点'
          });

          // 终点标记（红色）
          this.endMarker = new AMap.Marker({
            position: path[path.length - 1],
            icon: new AMap.Icon({
              size: new AMap.Size(25, 34),
              image: 'https://a.amap.com/jsapi_demos/static/demo-center/icons/poi-marker-red.png',
              imageSize: new AMap.Size(25, 34)
            }),
            offset: new AMap.Pixel(-13, -30),
            title: '终点'
          });
          this.mapInstance.add([this.startMarker, this.endMarker]);

          // 如果有有效路线，绘制路线
          if (path.length > 1) {
            // 根据交通方式设置不同的路线颜色
            let routeColor = '#FF8A45'; // 默认橙色（自驾）
            if (this.currentTrafficType === 'bus') {
              routeColor = '#1890FF'; // 蓝色（公交）
            } else if (this.currentTrafficType === 'taxi') {
              routeColor = '#52C41A'; // 绿色（打车）
            }

            // 创建新的路线覆盖物
            this.polylineInstance = new AMap.Polyline({
              path: path,
              strokeColor: routeColor,
              strokeWeight: 6,
              strokeOpacity: 0.8,
              strokeStyle: 'solid',
              lineJoin: 'round',
              lineCap: 'round'
            });

            // 添加到地图
            this.mapInstance.add(this.polylineInstance);

            // 自动调整视野以显示整条路线和标记
            const fitViewElements = [this.startMarker, this.endMarker];
            if (this.polylineInstance) {
              fitViewElements.push(this.polylineInstance);
            }

            // 绘制小吃店标记
            if (this.foodShops && this.foodShops.length > 0) {
              this.drawFoodMarkers(this.foodShops);
              // 将小吃店标记也加入视野调整
              fitViewElements.push(...this.foodMarkers);
            }

            // 自动调整视野
            this.mapInstance.setFitView(fitViewElements);
          } else {
            // 只有起点终点，没有中间路线
            this.mapInstance.setFitView([this.startMarker, this.endMarker]);
          }
        } else {
          // 没有 polyline 数据时，显示提示
          console.log('当前交通方式没有路线数据');
        }
        this.mapLoading = false; // 隐藏 loading
      } catch (error) {
        console.error('绘制路线失败:', error);
        this.$message.error('地图加载失败，请稍后重试');
        this.mapLoading = false;
      }
    },
    // 解析 polyline 坐标串
    parsePolyline(polyline) {
      if (!polyline) return [];
      try {
        // polyline 格式: "lng1,lat1;lng2,lat2;lng3,lat3;..."
        const points = polyline.split(';');
        const path = points.map(point => {
          const [lng, lat] = point.split(',').map(Number);
          return [lng, lat];
        });
        return path.filter(p => !isNaN(p[0]) && !isNaN(p[1]));
      } catch (error) {
        console.error('解析 polyline 失败:', error);
        return [];
      }
    },
    // 解析公交信息
    parseBusInfo(description) {
      if (!description) return '';

      // 尝试从描述中提取公交线路、站点数和步行距离
      // 示例格式："268路（乘坐6站） 步行300米" 或 "乘坐268路，换乘312路，步行500米"
      try {
        // 简单的格式化：如果包含“路”字，提取关键信息
        if (description.includes('路')) {
          return description;
        }
        return description;
      } catch (error) {
        return description;
      }
    },
    // 格式化费用显示
    formatCost(cost, type) {
      if (!cost && cost !== 0) return '￥0';

      // 打车费用显示区间
      if (type === 'taxi') {
        const minCost = Math.floor(cost * 0.9);
        const maxCost = Math.ceil(cost * 1.1);
        return `￥${minCost}~${maxCost}`;
      }

      // 其他交通方式显示固定费用
      return `￥${cost}`;
    },
    // 格式化路线描述为数字序号
    formatRouteDescription(description) {
      if (!description) return '';
      try {
        // 将"->"或"→"分隔的步骤转换为数字序号
        if (description.includes('→') || description.includes('->')) {
          const steps = description.split(/→|->/).map(s => s.trim()).filter(s => s);
          return steps.map((step, index) => `${index + 1}.${step}`).join('<br/>');
        }

        // 如果没有分隔符，直接返回原文本
        return description;
      } catch (error) {
        return description;
      }
    },
    // 绘制小吃店标记
    drawFoodMarkers(foodShops) {
      if (!this.mapInstance) return;

      // 清除旧的小吃店标记
      this.foodMarkers.forEach(marker => {
        this.mapInstance.remove(marker);
      });
      this.foodMarkers = [];

      // 为每个小吃店创建标记
      foodShops.forEach(shop => {
        // 尝试不同的字段名（兼容多种情况）
        const lng = shop.longitude || shop.lng || shop.shopLongitude || shop.shopLng;
        const lat = shop.latitude || shop.lat || shop.shopLatitude || shop.shopLat;

        // 检查经纬度是否有效（排除 null, undefined, 0, 空字符串）
        if (!lng || !lat) return;

        // 获取小吃图片 URL
        let foodImageUrl = '';
        if (shop.images) {
          try {
            const images = typeof shop.images === 'string' ? JSON.parse(shop.images) : shop.images;
            if (images && images.length > 0) {
              const imageId = images[0].id || images[0];
              foodImageUrl = config.backHost + '/file/download/' + imageId;
            }
          } catch (e) {
            console.error('解析小吃图片失败:', e);
          }
        }

        // 创建标记 - 使用小吃图片作为图标
        const marker = new AMap.Marker({
          position: [lng, lat],
          icon: new AMap.Icon({
            size: new AMap.Size(48, 48),
            // 图标尺寸
            image: foodImageUrl || 'https://webapi.amap.com/theme/v1.3/markers/n/mark_b.png',
            // 使用小吃图片，如果没有则使用默认标记
            imageSize: new AMap.Size(48, 48)
          }),
          offset: new AMap.Pixel(-24, -48),
          // 偏移量，使图片底部中心对准坐标点
          title: shop.name
        });

        // 设置信息窗体内容
        const infoContent = `
          <div style="padding: 0; min-width: 180px; border-radius: 8px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.15);">
            ${foodImageUrl ? `
            <div style="width: 100%; height: 100px; overflow: hidden;">
              <img src="${foodImageUrl}" style="width: 100%; height: 100%; object-fit: cover;" />
            </div>` : ''}
            <div style="padding: 10px; background: #fff;">
              <div style="font-size: 14px; font-weight: bold; color: #333; margin-bottom: 8px;">${shop.name}</div>
              <div style="font-size: 12px; color: #666; margin-bottom: 4px;">
                <i class="el-icon-location-outline" style="color: #FF8A45; margin-right: 4px;"></i>
                ${shop.address || '地址未知'}
              </div>
              <div style="display: flex; justify-content: space-between; align-items: center; margin-top: 8px;">
                <div style="font-size: 12px; color: #FF8A45; font-weight: bold;">
                  人均：￥${shop.avgPrice}
                </div>
                <div style="font-size: 11px; color: #999;">
                  距路线：${shop.distance}km
                </div>
              </div>
            </div>
          </div>
        `;

        // 创建信息窗体
        const infoWindow = new AMap.InfoWindow({
          content: infoContent,
          offset: new AMap.Pixel(0, -35)
        });

        // 点击标记显示信息窗体
        marker.on('click', () => {
          infoWindow.open(this.mapInstance, marker.getPosition());
        });

        // 添加到地图
        this.mapInstance.add(marker);
        this.foodMarkers.push(marker);
      });
    }
  }
};
